// Turn raw Google review objects into clean, flat fields.
// Reviews that already have an owner reply are skipped.
const starMap = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };

return $input.all()
  .filter(item => !item.json.reviewReply)
  .map(item => {
    const r = item.json;
    return {
      json: {
        review_id: r.reviewId || String(r.name || '').split('/').pop(),
        review_name: r.name || '',
        review_date: r.createTime || new Date().toISOString(),
        reviewer: r.reviewer?.displayName || 'Customer',
        star_rating: starMap[r.starRating] ?? (Number(r.starRating) || 0),
        review_text: (r.comment || '').trim()
      }
    };
  });

