// Merge the AI output back onto the review and lock tags to a fixed list,
// so the weekly star-loss math never sees made-up categories.
const allowed = ['wait_time','staff_behavior','price','cleanliness','product_quality','booking_scheduling','communication','none','other'];
const fixableCauses = new Set(['wait_time','staff_behavior','price','cleanliness','product_quality','booking_scheduling','communication']);
const reviews = $('Normalize Review Data').all();

return $input.all().map((item, i) => {
  let ai = item.json.message?.content ?? item.json.content ?? item.json.text ?? {};
  if (typeof ai === 'string') {
    try { ai = JSON.parse(ai.replace(/```json|```/g, '').trim()); } catch (e) { ai = {}; }
  }
  const review = reviews[i]?.json || {};
  const rootCause = allowed.includes(ai.root_cause) ? ai.root_cause : 'other';
  const autoPost = review.star_rating >= 4 && rootCause === 'none';

  return {
    json: {
      review_id: review.review_id,
      review_name: review.review_name,
      review_date: review.review_date,
      reviewer: review.reviewer,
      star_rating: review.star_rating,
      review_text: review.review_text,
      sentiment: ai.sentiment || 'neutral',
      root_cause: rootCause,
      staff_mentioned: ai.staff_mentioned || '',
      fixable: fixableCauses.has(rootCause),
      complaint_summary: ai.complaint_summary || '',
      draft_reply: ai.reply || '',
      reply_status: autoPost ? 'auto_posted' : 'pending_approval'
    }
  };
});

