// Score each fixable root cause by stars lost in the last 7 days.
// Stars lost per review = 5 - rating (a 2-star review costs 3 stars).
const labels = {
  wait_time: 'Wait time',
  staff_behavior: 'Staff behaviour',
  price: 'Price / value',
  cleanliness: 'Cleanliness',
  product_quality: 'Product or service quality',
  booking_scheduling: 'Booking & scheduling',
  communication: 'Communication'
};

const rows = $input.all().map(i => i.json);
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const week = rows.filter(r => {
  const d = new Date(r.review_date);
  return !isNaN(d) && d >= weekAgo;
});

const total = week.length;
const avg = total ? week.reduce((s, r) => s + Number(r.star_rating || 0), 0) / total : 0;

const byCause = {};
for (const r of week) {
  if (String(r.fixable).toLowerCase() !== 'true') continue;
  const lost = Math.max(0, 5 - Number(r.star_rating || 5));
  if (!lost) continue;
  const key = r.root_cause;
  byCause[key] ??= { cause: key, label: labels[key] || key, stars_lost: 0, reviews: 0, examples: [], staff: {} };
  const c = byCause[key];
  c.stars_lost += lost;
  c.reviews += 1;
  if (r.complaint_summary && c.examples.length < 5) c.examples.push(`${r.star_rating}★ – ${r.complaint_summary}`);
  if (r.staff_mentioned) c.staff[r.staff_mentioned] = (c.staff[r.staff_mentioned] || 0) + 1;
}

const ranked = Object.values(byCause).sort((a, b) => b.stars_lost - a.stars_lost || b.reviews - a.reviews);
const top = ranked[0] || null;

return [{
  json: {
    period_start: weekAgo.toISOString().slice(0, 10),
    period_end: now.toISOString().slice(0, 10),
    total_reviews: total,
    average_rating: Number(avg.toFixed(2)),
    total_stars_lost_to_fixable_issues: ranked.reduce((s, c) => s + c.stars_lost, 0),
    top_problem: top,
    ranking: ranked.map(c => ({ label: c.label, stars_lost: c.stars_lost, reviews: c.reviews }))
  }
}];
